class KthLargestSort:
    def __init__(self, k, nums):
        self.k = k
        self.nums = list(nums)          # 保存完整数据流

    def add(self, val):
        self.nums.append(val)           # 新数据入流
        arr = sorted(self.nums)         # 每次全排序 O(n log n)
        return arr[-self.k]             # 第 k 大 = 升序倒数第 k 个

class KthLargestArray:
    def __init__(self, k, nums):
        self.k = k
        self.top = sorted(nums, reverse=True)[:k]   # 初始前 k 大

    def add(self, val):
        if len(self.top) < self.k:
            self.top.append(val)        # 候选不足 k 个，直接收
        else:
            min_i = self.top.index(min(self.top))   # O(k) 找最小候选
            if val > self.top[min_i]:
                self.top[min_i] = val   # 淘汰最小候选
        return min(self.top)            # 候选中最小者 = 第 k 大

