class KthLargest {
public:
    KthLargest(int k, vector<int>& nums) : k(k) {
        // 初始化：逐个入堆，保持堆中只有当前最大的 k 个候选
        for (int x : nums) {
            heap.push(x);
            if ((int)heap.size() > k)
                heap.pop();          // 超员淘汰最小候选
        }
    }

    int add(int val) {
        heap.push(val);              // 新数据入流
        if ((int)heap.size() > k)
            heap.pop();              // 超过 k 个就弹出堆顶，淘汰最小候选
        return heap.top();           // 堆顶 = 前 k 大中最小 = 第 k 大
    }

private:
    int k;
    priority_queue<int, vector<int>, greater<int>> heap;   // 大小为 k 的最小堆
};

