// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：
//   第一行：k m（第 k 大、初始数据流长度）
//   第二行：m 个整数（初始数据流，可为空）
//   第三行：q（add 调用次数）
//   第四行：q 个整数（依次 add 的参数）
// 输出格式：q 行，每行一个整数，为该次 add 后的第 k 大元素
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int k, m;
    cin >> k >> m;
    priority_queue<int, vector<int>, greater<int>> heap;   // 大小为 k 的最小堆
    for (int i = 0; i < m; ++i) {   // 初始数据流逐个入堆
        int x;
        cin >> x;
        heap.push(x);
        if ((int)heap.size() > k)   // 超员淘汰最小候选
            heap.pop();
    }
    int q;
    cin >> q;
    for (int i = 0; i < q; ++i) {
        int val;
        cin >> val;
        heap.push(val);             // 新数据入流
        if ((int)heap.size() > k)   // 超员淘汰最小候选
            heap.pop();
        cout << heap.top() << '\n'; // 堆顶即第 k 大
    }
    return 0;
}

