class KthLargest {
    private final int k;
    private final PriorityQueue<Integer> heap = new PriorityQueue<>();  // 大小为 k 的最小堆

    public KthLargest(int k, int[] nums) {
        this.k = k;
        // 初始化：逐个入堆，保持堆中只有当前最大的 k 个候选
        for (int x : nums) {
            heap.offer(x);
            if (heap.size() > k)
                heap.poll();       // 超员淘汰最小候选
        }
    }

    public int add(int val) {
        heap.offer(val);           // 新数据入流
        if (heap.size() > k)
            heap.poll();           // 超过 k 个就弹出堆顶，淘汰最小候选
        return heap.peek();        // 堆顶 = 前 k 大中最小 = 第 k 大
    }
}

