// 最小堆的两个辅助操作
function heapPush(heap, x) {
  heap.push(x);                // 新元素先放到堆底
  let i = heap.length - 1;
  while (i > 0) {              // 上浮：比父节点小就交换
    const p = (i - 1) >> 1;
    if (heap[i] >= heap[p]) break;
    [heap[i], heap[p]] = [heap[p], heap[i]];
    i = p;
  }
}

function heapPop(heap) {
  const top = heap[0];         // 弹出堆顶（最小候选）
  const last = heap.pop();
  if (heap.length) {
    heap[0] = last;            // 末尾元素补到堆顶
    let i = 0;
    for (;;) {                 // 下沉：与较小的孩子交换
      const l = 2 * i + 1, r = 2 * i + 2;
      let m = i;
      if (l < heap.length && heap[l] < heap[m]) m = l;
      if (r < heap.length && heap[r] < heap[m]) m = r;
      if (m === i) break;
      [heap[i], heap[m]] = [heap[m], heap[i]];
      i = m;
    }
  }
  return top;
}

/**
 * 数据流第 k 大：核心是维护『当前最大的 k 个数』的最小堆，堆顶即第 k 大
 * @param {number} k
 * @param {number[]} nums
 */
var KthLargest = function (k, nums) {
  this.k = k;
  this.heap = [];  // 大小为 k 的最小堆
  for (const x of nums) {
    heapPush(this.heap, x);                        // 逐个入堆
    if (this.heap.length > k) heapPop(this.heap);  // 超员淘汰最小候选
  }
};

/**
 * @param {number} val
 * @return {number}
 */
KthLargest.prototype.add = function (val) {
  heapPush(this.heap, val);    // 新数据入流
  if (this.heap.length > this.k)
    heapPop(this.heap);        // 超过 k 个就弹出堆顶，淘汰最小候选
  return this.heap[0];         // 堆顶 = 前 k 大中最小 = 第 k 大
};

