type KthLargest struct {
	k    int
	heap []int // 大小为 k 的最小堆（手写 sift，不依赖标准库）
}

// heapPush 向最小堆压入元素（上浮）
func heapPush(h *[]int, x int) {
	*h = append(*h, x) // 新元素先放到堆底
	i := len(*h) - 1
	for i > 0 { // 上浮：比父节点小就交换
		p := (i - 1) / 2
		if (*h)[i] >= (*h)[p] {
			break
		}
		(*h)[i], (*h)[p] = (*h)[p], (*h)[i]
		i = p
	}
}

// heapPop 弹出最小堆堆顶（下沉）
func heapPop(h *[]int) int {
	hp := *h
	top := hp[0] // 弹出堆顶
	*h = hp[:len(hp)-1]
	if len(*h) > 0 {
		(*h)[0] = hp[len(hp)-1] // 末尾元素补到堆顶
		i, sz := 0, len(*h)
		for { // 下沉：与较小的孩子交换
			l, r, m := 2*i+1, 2*i+2, i
			if l < sz && (*h)[l] < (*h)[m] {
				m = l
			}
			if r < sz && (*h)[r] < (*h)[m] {
				m = r
			}
			if m == i {
				break
			}
			(*h)[i], (*h)[m] = (*h)[m], (*h)[i]
			i = m
		}
	}
	return top
}

func KthLargestConstructor(k int, nums []int) KthLargest {
	this := KthLargest{k: k}
	for _, x := range nums { // 逐个入堆，保持只存当前最大的 k 个
		heapPush(&this.heap, x)
		if len(this.heap) > k {
			heapPop(&this.heap) // 超员淘汰最小候选
		}
	}
	return this
}

func (this *KthLargest) Add(val int) int {
	heapPush(&this.heap, val) // 新数据入流
	if len(this.heap) > this.k {
		heapPop(&this.heap) // 超过 k 个就弹出堆顶，淘汰最小候选
	}
	return this.heap[0] // 堆顶 = 前 k 大中最小 = 第 k 大
}
